# Standard leap year rule verification
def is_leap_year_correct(y):
    return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)

def is_leap_year_current(y):
    return (y % 4 == 0 and y % 100 != 0) or y % 400 == 0

test_years = [2000, 1900, 2024, 2023, 2100, 2400, 1800, 1600]
for y in test_years:
    c = is_leap_year_correct(y)
    curr = is_leap_year_current(y)
    match = '✓' if c == curr else '✗'
    print(f'{match} Year {y}: correct={c}, current={curr}')
